        const adults = `${variation.adult_nbr} ${variation.adult_nbr === 1 ? locales_store.locales.entries['Lcz_Adult']?.toLowerCase() : locales_store.locales.entries['Lcz_Adults']?.toLowerCase()}`;
        const children = variation.child_nbr > 0
